  // Migration 1: Premium cuts per piece pricing
  const sql1 = fs.readFileSync\(''supabase/migrations/20260216_premium_cuts_per_piece_pricing.sql'', ''utf8''\);

  // Split SQL into individual statements \(skip comments and empty lines\)
  const statements = sql1.split\('';''\).map\(s => s.trim\(\)\).filter\(s => s && !s.startsWith\(''--''\)\);

  for \(const stmt of statements\) {
    // Extract the slug from WHERE clause
    const slugMatch = stmt.match\(/WHERE slug = ''\([^'']+\)''/\);
    if \(!slugMatch\) continue;
    const slug = slugMatch[0];
    console.log\(''Running update for:'', slug\);

    // Use raw SQL via pg - but supabase-js doesn''t have raw SQL
    // Instead, use the REST API to do partial updates
  }

  // Actually, let''s just use supabase-js to do direct updates
  // Migration 1: Guanciale
  let { data, error } = await supabase
    .from\(''extras_catalog''\)
